INSERT OR REPLACE INTO cms_items (c_id, i_id, title, pic, content, addtime) VALUES (120, 276, 'LOWER WEIGHT COATED PAPER', '../upload/image/20181227/20181227121111_41698.jpg', '<p></p><p align="center" style="color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="background:white;color:black;font-size:13.5pt;"><span style=''font-family:"font-size:22px;''><span style="background:white;color:black;font-size:13.5pt;"><span style="font-size:24px;"><strong><span style="font-size:24px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">LOWER WEIGHT COATED PAPER</span><br/> <br/> </span></strong></span></span></span></span></p> <p class="" style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">LWC, called Light Weight Coated Paper. It refers to a class of low weight coated paper processing, generally in the 40-90g/m2. This kind of paper front and back are coated with a layer of thin coating (composed of calcium carbonate and cationic starch), and then through a super calendar so as to improve its physical properties and printability. The chemical composition of this paper, the long fiber bleached softwood chemical pulp 40%; mechanical wood pulp accounted for 60%. </span></span></p> <h6 class="" style="text-align:left;color:#59595B;text-indent:0px;font-family:宋体;font-style:normal;background-color:#FFFFFF;"> <span style="font-size:20px;"><span style="font-size:20px;"><br/> </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;"><span style="color:#E53333;font-family:Tahoma;font-size:18px;">The performance of paper</span></span></span> </h6> <p class="" style="text-align:left;color:#59595B;text-indent:20pt;font-family:宋体;font-size:12px;font-style:normal;font-weight:normal;background-color:#FFFFFF;"> <span style="font-size:20px;"><span style="font-size:20px;"><span style="font-size:24px;"><br/> </span><span style="color:#E53333;font-family:Tahoma;font-size:18px;">1. This kind of paper between the performance of coated paper and offset paper, the effect of its color printing comparable to coated paper, and its opacity, smoothness, gloss and printability is good. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">2. This kind of paper and low cost. It costs between the coated paper and offset paper between. However, the printing quality can be achieved comparable with the effect of coated paper, so a high value-added paper.</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">3. However, the durability of this paper is small, so the long-term retention of printed materials is not easy. </span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;"> Usage:</span><br/> <span style="color:#E53333;font-family:Tahoma;font-size:18px;">This paper is mainly used for printing magazines, catalogs, advertising, trademarks, newspaper inserts and so on</span>.<br/> </span></span></p>', '2026-09-06 20:58:45');
